{"results": [{"id": "hp_doc_fcae434ee772edcaa9a88a4ff546523302d2cb56c4e82f4a18c0a1e8b0fa1cbf", "title": "The Grass Harp (film)", "text": "The Grass Harp is a 1995 American comedy-drama film based on the novella by Truman Capote; the screenplay was the final work of Oscar-winning screenwriter Stirling Silliphant. The film was directed by Charles Matthau, and starred Piper Laurie, Sissy Spacek, the director's father Walter Matthau, Edward Furlong, and Nell Carter. Piper Laurie won the Best Supporting Actress award from the Southeastern Film Critics Association for her work on the film.", "score": 28.7124}, {"id": "hp_doc_d9cfd0754f07f8dc015c085fb01ca3b7d3cb3e40c30e7abbe0e9f00c032ba5ab", "title": "The Grass Harp (disambiguation)", "text": "The Grass Harp is a 1951 novel by Truman Capote.", "score": 26.7605}, {"id": "hp_doc_f8df8f90e4b88465a35c281f451836b28beef0e5ffbe5372403ca586ccd50a87", "title": "The Grass Harp (play)", "text": "The Grass Harp is a play written by Truman Capote based on his novel of the same name. Producer Saint Subber staged it on Broadway in 1952. It was Capote's first play.", "score": 24.6043}], "remaining_searches": 2}
